import 'package:flutter/material.dart';import '../data/app_store.dart';import '../models/procedure_models.dart';import '../theme/operon_theme.dart';import 'procedure_run_screen.dart';
class ProceduresScreen extends StatefulWidget{final AppStore store;const ProceduresScreen({super.key,required this.store});@override State<ProceduresScreen> createState()=>_S();}
class _S extends State<ProceduresScreen>{@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Procedures & checklists')),body:ListView(padding:const EdgeInsets.only(bottom:30),children:[const Padding(padding:EdgeInsets.all(16),child:Text('Use only site-controlled procedures. OPERON records operator progress; it does not replace the approved procedure, DCS/SIS, PTW or LOTO.',style:TextStyle(color:OperonTheme.muted))),...widget.store.controlledProcedures.map((p)=>Card(margin:const EdgeInsets.symmetric(horizontal:16,vertical:6),child:ListTile(onTap:()=>_open(p),leading:const Icon(Icons.fact_check,color:OperonTheme.teal),title:Text(p.title,style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text('${p.category} · v${p.version}\n${p.source}'),isThreeLine:true,trailing:const Icon(Icons.play_circle_outline)))),if(widget.store.procedureRuns.isNotEmpty)...[const Padding(padding:EdgeInsets.fromLTRB(16,24,16,8),child:Text('RUN HISTORY',style:TextStyle(color:OperonTheme.muted,fontSize:11,fontWeight:FontWeight.w900))),...widget.store.procedureRuns.take(12).map((r)=>ListTile(leading:Icon(r.state==ProcedureRunState.completed?Icons.check_circle:Icons.history,color:r.state==ProcedureRunState.completed?OperonTheme.teal:Colors.orange),title:Text(r.procedureTitle),subtitle:Text('v${r.version} · ${r.operatorName} · ${r.state.name}')))] ]));void _open(ControlledProcedure p){final active=widget.store.procedureRuns.where((r)=>r.procedureId==p.id&&(r.state==ProcedureRunState.active||r.state==ProcedureRunState.paused));final r=active.isNotEmpty?active.first:widget.store.startProcedure(p);Navigator.push(context,MaterialPageRoute(builder:(_)=>ProcedureRunScreen(store:widget.store,procedure:p,run:r))).then((_)=>setState((){}));}}
